const today = new Date().toISOString().slice(0, 10);
const paused = String($env.DAILY_PAUSED ?? '').toLowerCase() === 'true';
// Quota gate: skip the day's run when paused or when the monthly video budget
// is exhausted. Budget accounting is a TODO until a backend usage endpoint
// exposes per-month job counts (GET /api/v1/usage exists but is not
// month-scoped for video jobs yet).
const monthlyTarget = 50;
return [{ json: { date: today, runToday: !paused, monthlyTarget,
  reason: paused ? 'DAILY_PAUSED=true' : 'quota ok (budget check TODO)' } }];

